 fn instance() -> &'static mut Inner {
     if unlikely(!INSTANCE_INIT.load(ORDER)) {
         panic!("frame allocator used before init()");
     }

     // SAFETY: `INSTANCE_INIT` is `true`, so `INSTANCE` has been fully written by `init()`.
